description:
{
  "image_category": "MARKING_AND_SIGNAL",
  "summary": "Hình ảnh minh họa quy cách bố trí vạch kẻ đường (vạch tim và vạch phân chia làn) tại một nút giao thông phức tạp, bao gồm các đoạn đường cong và khu vực nhập/làn xe.",
  "items": [
    {
      "identifier": "Vạch phân chia hai chiều xe chạy (Vạch 1.1)",
      "visual_or_geometric_features": "Vạch đơn, đứt nét, màu vàng. Bề rộng nét vẽ b = 15 cm. Tỷ lệ chiều dài đoạn nét liền L1 và đoạn nét đứt L2 là 1:2.",
      "meaning_or_specification": "Dùng để phân chia hai chiều xe chạy ngược chiều. Xe được phép cắt qua để sử dụng làn ngược chiều từ cả hai phía."
    },
    {
      "identifier": "Vạch phân chia hai chiều xe chạy (Vạch 1.3)",
      "visual_or_geometric_features": "Vạch đôi song song, nét liền, màu vàng. Bề rộng nét vẽ b = 15 cm. Khoảng cách phía trong hai mép vạch đơn nhỏ nhất là 15 cm, lớn nhất là 50 cm.",
      "meaning_or_specification": "Dùng để phân chia hai chiều xe chạy ngược chiều, xe không được lấn làn, không được đè lên vạch. Thường dùng cho đường có từ 4 làn xe cơ giới trở lên hoặc ở các vị trí cần thiết khác."
    },
    {
      "identifier": "Vạch phân chia hai chiều xe chạy (Vạch 1.4)",
      "visual_or_geometric_features": "Vạch đôi song song, gồm một vạch nét liền và một vạch nét đứt, màu vàng. Bề rộng nét vẽ b = 15 cm. Tỷ lệ L1/L2 = 1:2.",
      "meaning_or_specification": "Dùng để phân chia hai chiều xe chạy ngược chiều. Xe trên làn tiếp giáp vạch đứt được phép cắt qua; xe trên làn tiếp giáp vạch liền không được lấn làn hoặc đè lên vạch."
    },
    {
      "identifier": "Vạch phân chia hai chiều xe chạy (Vạch 1.5)",
      "visual_or_geometric_features": "Vạch đôi, đứt nét, màu vàng. Bề rộng nét vẽ b = 15 cm. Tỷ lệ L1:L2 = 1:3.",
      "meaning_or_specification": "Dùng để xác định ranh giới làn đường có thể thay đổi hướng xe chạy theo thời gian (theo quy định của người điều khiển giao thông, tín hiệu đèn, biển báo...)."
    },
    {
      "identifier": "Vạch phân chia các làn xe cùng chiều (Vạch 2.1)",
      "visual_or_geometric_features": "Vạch đơn, đứt nét, màu trắng. Bề rộng nét vẽ b = 15 cm. Tỷ lệ L1/L2 = 1:3.",
      "meaning_or_specification": "Dùng để phân chia các làn xe cùng chiều. Xe được phép thực hiện việc chuyển làn đường qua vạch này."
    },
    {
      "identifier": "Vạch phân chia các làn xe cùng chiều (Vạch 2.2)",
      "visual_or_geometric_features": "Vạch đơn, liền nét, màu trắng. Bề rộng vạch 15 cm.",
      "meaning_or_specification": "Dùng để phân chia các làn xe cùng chiều trong trường hợp không cho phép xe chuyển làn hoặc sử dụng làn khác; xe không được lấn làn, không được đè lên vạch."
    },
    {
      "identifier": "Vạch phân chia các làn xe cùng chiều (Vạch 2.4)",
      "visual_or_geometric_features": "Vạch kép (một vạch liền, một vạch đứt nét), màu trắng.",
      "meaning_or_specification": "Dùng để phân chia các làn xe cùng chiều. Xe trên làn tiếp giáp vạch đứt được phép cắt qua khi cần thiết; xe trên làn tiếp giáp vạch liền không được lấn làn hoặc đè lên vạch."
    }
  ]
}
